  `device_type` varchar(100) NOT NULL DEFAULT 'Teltonika FMB125',
  `server_address` varchar(150) NOT NULL DEFAULT 'nl.gpsgsm.org:21448',
  `unique_id` varchar(100) DEFAULT NULL,
